def is_multiply_prime(a):
    """Returns a tuple (is_product_of_three_primes, even_digit_count, odd_digit_count) for the prime factors."""

    # Helper function to check if a number is prime
    def is_prime(n: int) -> bool:
        if n < 2:
            return False
        for j in range(2, int(n**0.5) + 1):
            if n % j == 0:
                return False
        return True

    # Helper function to count even and odd digits in a number
    def even_odd_count(num: int) -> tuple:
        even = 0
        odd = 0
        for digit in str(abs(num)):
            if int(digit) % 2 == 0:
                even += 1
            else:
                odd += 1
        return (even, odd)

    # Iterate over all possible triplets of primes
    for i in range(2, 101):
        if not is_prime(i):
            continue
        for j in range(2, 101):
            if not is_prime(j):
                continue
            for k in range(2, 101):
                if not is_prime(k):
                    continue
                if i * j * k == a:
                    # Count even and odd digits across all three primes
                    e1, o1 = even_odd_count(i)
                    e2, o2 = even_odd_count(j)
                    e3, o3 = even_odd_count(k)
                    total_even = e1 + e2 + e3
                    total_odd = o1 + o2 + o3
                    return (True, total_even, total_odd)
    return (False, 0, 0)

