def hex_key(num):
    primes = {'2':2, '3':3, '5':5, '7':7, 'B':11, 'D':13}
    total = 0
    for idx, ch in enumerate(num):
        if idx % 2 == 0 and ch in primes:
            total += primes[ch]
    return total

