def decimal_to_binary(decimal):
    binary_str = bin(decimal)[2:]
    l = len(binary_str)
    count = 0
    if l == 0:
        return 0
    pat = binary_str + binary_str
    for i in range(l):
        rotation = pat[i:i+l]
        if rotation in binary_str:
            count += 1
    return count

