def modified_prime_length(string):
    l = len(string)
    if l == 0 or l == 1:
        return 0
    # Check if l is prime
    is_prime = True
    for i in range(2, l):
        if l % i == 0:
            is_prime = False
            break
    if not is_prime:
        return 0
    # Count all substrings with prime length
    count = 0
    for i in range(len(string)):
        for j in range(i + 1, len(string) + 1):
            sub_len = j - i
            if sub_len < 2:
                continue
            is_sub_prime = True
            for k in range(2, int(sub_len ** 0.5) + 1):
                if sub_len % k == 0:
                    is_sub_prime = False
                    break
            if is_sub_prime:
                count += 1
    return count

