def skjkasdkd(lst):
    """You are given a list of integers.
    You need to find the largest prime value, compute the sum of all primes in the list, and return the GCD of the sum and the largest prime.

    Examples:
    For lst = [0,3,2,1,3,5,7,4,5,5,5,2,181,32,4,32,3,2,32,324,4,3] the output should be 1
    For lst = [1,0,1,8,2,4597,2,1,3,40,1,2,1,2,4,2,5,1] the output should be 1
    For lst = [1,3,1,32,5107,34,83278,109,163,23,2323,32,30,1,9,3] the output should be 1
    For lst = [0,724,32,71,99,32,6,0,5,91,83,0,5,6] the output should be 1
    For lst = [0,81,12,3,1,21] the output should be 0
    For lst = [0,8,1,2,1,7] the output should be 1
    """

    def isPrime(n: int) -> bool:
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    def greatest_common_divisor(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    primes = []
    for num in lst:
        if isPrime(num):
            primes.append(num)

    if not primes:
        return 0

    max_prime = max(primes)
    sum_primes = sum(primes)
    result = greatest_common_divisor(sum_primes, max_prime)
    return result

