def closest_integer(value):
    from math import floor, ceil

    if value.count('.') == 1:
        while value[-1] == '0':
            value = value[:-1]

    num = float(value)
    decimal_part = num % 1.0

    if abs(decimal_part - 0.5) < 1e-9:
        integer_part = int(num)
        if integer_part % 2 == 0:
            res = floor(num)
        else:
            res = ceil(num)
    else:
        res = int(round(num))
    return res

