def select_words(s, n):
    """Given a string s and a natural number n, returns a tuple (a, b), where 'a' is the maximum length of words with exactly n consonants, and 'b' is the minimum length of such words. If no such words exist, returns (None, None)."""
    result = []
    for word in s.split():
        consonant_count = 0
        for char in word:
            if char.lower() not in "aeiou":
                consonant_count += 1
        if consonant_count == n:
            result.append(word)
    if not result:
        return (None, None)
    max_length = max(len(word) for word in result)
    min_length = min(len(word) for word in result)
    return (max_length, min_length)

