def get_closest_vowel(word):
    """You are given a word. Your task is to find the closest vowel that stands between 
    two consonants from the right side of the word (case sensitive), and return the sum of ASCII values of such vowels that are located at even indices.

    Vowels in the beginning and ending don't count. Return 0 if no such vowel is found.

    You may assume that the given string contains English letters only.

    Example:
    get_closest_vowel("yogurt") ==> 0
    get_closest_vowel("FULL") ==> 0
    get_closest_vowel("quick") ==> 0
    get_closest_vowel("ab") ==> 0
    """

    if len(word) < 3:
        return 0

    vowels = {"a", "e", "i", "o", "u", "A", "E", 'O', 'U', 'I'}
    total = 0

    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels:
            if (word[i + 1] not in vowels) and (word[i - 1] not in vowels):
                if i % 2 == 0:
                    total += ord(word[i])

    return total

