def maximum(arr, k):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, n - 1):
            if n % i == 0:
                return False
        return True

    if k == 0:
        return []

    non_primes = [x for x in arr if not is_prime(x)]

    if len(non_primes) < k:
        return sorted(non_primes)
    else:
        non_primes_sorted = sorted(non_primes, reverse=True)
        top_k = non_primes_sorted[:k]
        return sorted(top_k)

