def get_odd_collatz(n):
    """
    Given a positive integer n, return a tuple containing the two closest odd numbers in the Collatz sequence.
    If only one odd number exists, return a tuple with the same number twice.
    """
    if n % 2 == 0:
        odd_collatz = []
    else:
        odd_collatz = [n]
    while n > 1:
        if n % 2 == 0:
            n = n / 2
        else:
            n = n * 3 + 1
        if n % 2 == 1:
            odd_collatz.append(int(n))
    sorted_odds = sorted(odd_collatz)
    if len(sorted_odds) == 1:
        return (sorted_odds[0], sorted_odds[0])
    closest_pair = None
    min_distance = float('inf')
    for i in range(len(sorted_odds)):
        for j in range(i + 1, len(sorted_odds)):
            distance = abs(sorted_odds[i] - sorted_odds[j])
            if distance < min_distance:
                min_distance = distance
                closest_pair = (sorted_odds[i], sorted_odds[j])
    return closest_pair

