def even_odd_palindrome(n):
    def is_palindrome(n: int) -> bool:
        return str(n) == str(n)[::-1]

    even_palindromes = []
    odd_palindromes = []
    for i in range(1, n + 1):
        if is_palindrome(i):
            if i % 2 == 0:
                even_palindromes.append(i)
            else:
                odd_palindromes.append(i)

    # Apply can_arrange logic to even_palindromes
    ind_even = -1
    for i in range(1, len(even_palindromes)):
        if even_palindromes[i] < even_palindromes[i - 1]:
            ind_even = i

    # Apply can_arrange logic to odd_palindromes
    ind_odd = -1
    for i in range(1, len(odd_palindromes)):
        if odd_palindromes[i] < odd_palindromes[i - 1]:
            ind_odd = i

    return (len(even_palindromes), len(odd_palindromes), ind_even, ind_odd)

