def advanced_fix_spaces(text):
    def factorize(n: int) -> list:
        import math
        fact = []
        if n == 1:
            return [1]
        i = 2
        while i <= int(math.sqrt(n) + 1):
            if n % i == 0:
                fact.append(i)
                n //= i
            else:
                i += 1
        if n > 1:
            fact.append(n)
        return fact

    new_text = ""
    i = 0
    start, end = 0, 0
    while i < len(text):
        if text[i] == " ":
            end += 1
        else:
            count = end - start
            if count > 2:
                factors = factorize(count)
                factor_str = '-'.join(map(str, factors))
                new_text += factor_str + text[i]
            elif count > 0:
                factors = factorize(count)
                factor_str = '_'.join(map(str, factors))
                new_text += factor_str + text[i]
            else:
                new_text += text[i]
            start, end = i + 1, i + 1
        i += 1

    count = end - start
    if count > 2:
        factors = factorize(count)
        factor_str = '-'.join(map(str, factors))
        new_text += factor_str
    elif count > 0:
        factors = factorize(count)
        factor_str = '_'.join(map(str, factors))
        new_text += factor_str

    return new_text

